class StringEnum(String):
    """Store an enum by the names of its values"""
    def __init__(self, enum):
        self.enum = enum
        super().__init__()

    def dynamo_load(self, value):
        value = super().dynamo_load(value)
        return self.enum[value]

    def dynamo_dump(self, value):
        value = value.name
